-- Generated from livelabs-reserved-public-ips.xlsx. Review before execution.
-- This idempotent seed leaves IPs already allocated to a reservation unchanged.
-- Generated 1500 inventory rows.

MERGE INTO ll_reserved_public_ips target
USING (
  SELECT
    'LiveLabs-PublicIP-00001' AS name,
    '144.24.32.28' AS ip_address,
    'ocid1.publicip.oc1.phx.amaaaaaaqwyowyyaayheaxogwetkjkgqgqsu6njq6egcpsy7xbmwajg7c6ia' AS ip_ocid,
    'ocid1.tenancy.oc1..aaaaaaaayz6bptazeg7qiqy4rt4k3otxi5umailp3rzeio6cc3ubub2n26ia' AS tenancy_ocid,
    'us-phoenix-1' AS region_identifier,
    'llenv00001.livelabsenv1.oracle.com' AS dns_entry,
    'llenv00001.livelabsenv1.oracle.com' AS cert_common_name,
    'ocid1.certificate.oc1.phx.amaaaaaaqwyowyyai4gtpuvhrymv5nf3b4ilxvrdd2va6b4kj45aoi6ibdvq' AS cert_ocid,
    'ocid1.cabundle.oc1.phx.amaaaaaaqwyowyyabycuqylltw2lloiebueu6ztdvruz7ocba3llywmjenia' AS ca_bundle_ocid,
    'Y' AS active_flg
  FROM dual
) source
ON (target.ip_ocid = source.ip_ocid)
WHEN MATCHED THEN UPDATE SET
  target.name = source.name,
  target.ip_address = source.ip_address,
  target.tenancy_id = (SELECT id FROM ll_tenancies WHERE tenancy_ocid = source.tenancy_ocid),
  target.region_id = (SELECT id FROM ll_oci_regions WHERE region_identifier = source.region_identifier),
  target.dns_entry = source.dns_entry,
  target.cert_common_name = source.cert_common_name,
  target.cert_ocid = source.cert_ocid,
  target.ca_bundle_ocid = source.ca_bundle_ocid,
  target.active_flg = source.active_flg
  WHERE target.reservation_id IS NULL
WHEN NOT MATCHED THEN INSERT (
  name, ip_address, ip_ocid, tenancy_id, region_id, dns_entry,
  cert_common_name, cert_ocid, ca_bundle_ocid, active_flg
) VALUES (
  source.name, source.ip_address, source.ip_ocid,
  (SELECT id FROM ll_tenancies WHERE tenancy_ocid = source.tenancy_ocid),
  (SELECT id FROM ll_oci_regions WHERE region_identifier = source.region_identifier),
  source.dns_entry, source.cert_common_name, source.cert_ocid,
  source.ca_bundle_ocid, source.active_flg
);

